// Presentation-only classification. A confirmed own write is identified ONLY by
// the binding's authoritative needsReload discriminator, never by error wording.
export function sg2SaveNotice(state,{terminalPending=false,profileMode=state.profileMode===true}={}){
 if(state.actionsBlocked)return {title:'정밀검사에서 기록을 확인하지 못했어요',detail:'다음 진행과 저장을 막아 둬요.'};
 if(state.conflict&&state.conflictKind==='saved-then-changed')return {title:'이 탭의 변경은 저장됐어요.',detail:'그 뒤 다른 탭에서 저장 기록이 바뀌었어요. 현재 저장된 기록을 다시 불러와 주세요.'};
 if(state.conflict)return {title:'다른 탭에서 저장 기록이 바뀌었어요. 자동으로 합치거나 덮어쓰지 않아요.',detail:state.pending?'이 탭의 변경을 파일로 내보내 보관한 뒤 새로고침해 주세요.':'현재 저장된 기록을 다시 불러와 주세요.'};
 if(state.pending)return {title:terminalPending?SG2_COPY.terminalPending:profileMode?SG2_COPY.profilePending:SG2_COPY.pending,detail:terminalPending?SG2_COPY.terminalHelp:SG2_COPY.pendingHelp};
 if(state.recoveryRequired)return {title:profileMode?'프로필 저장을 확인하지 못했어요':'원정 저장을 확인하지 못했어요',detail:SG2_COPY.unverifiedHelp};
 return {title:state.error||'',detail:''};
}
export function sg2ExportLabel(state,{terminalPending=false}={}){return state.recoveryRequired?'확인하지 못한 저장 자료 내보내기':state.profileMode?'프로필 전체 내보내기':terminalPending?'결과 포함 기록 내보내기':'원정 기록 내보내기';}
// New private executable host. PA5 owns commands, save bytes and trust. R2 owns
