   const sameRead=status?.ownerId===ticket.ownerId&&status?.requestId===ticket.requestId;
   if(!sameRead||ticket.source!==(m.profileMode?profile:model)||['cancelled','failed'].includes(status?.status)||m.pending||m.error||m.conflict||m.actionsBlocked||m.controller&&m.controller!==ticket.controller){asyncTerminal=null;}
