   const before=ack?.state.phase,beforeService=ack?.state.pendingService?.id,next=m.run?Object.freeze(m.run):null; // Worker-owned read projection, never a save/commit input. Do not clone whole history on the main thread.
   const accepted=asyncTerminal&&status?.status==='ready'&&next?.runId===ticket.runId&&next.revision===ticket.revision+1&&next.state.battles.length===ticket.battles+1&&next.state.phase!=='battle'&&next.state.battles.at(-1)?.receipt?.result?.battleId===ticket.battleId&&canonical(next.state.battles.at(-1).receipt)===canonical(ticket.liveReceipt);
   ackSource=m.run;ack=next;asyncTerminal=null;
   if(before!==ack?.state.phase){if(!(playerMode&&externalStartup))tab='route';selected=null;serviceTarget=null;}if(beforeService!==ack?.state.pendingService?.id){serviceSelected=null;servicePane='list';}
