  if(playerMode&&!notice.title&&(profile?.state.pending||profile?.state.conflict)){const pNotice=sg2SaveNotice(profile.state,{profileMode:true});notice.title=pNotice.title;notice.detail=pNotice.detail;}
  if(!notice.title&&profile?.state.recoveryRequired){notice.title='프로필 저장을 확인하지 못했어요';notice.detail='독립 원정은 계속할 수 있어요.';}
  node.hidden=!notice.title;node.innerHTML=esc(notice.title)+(notice.detail?`<p>${esc(notice.detail)}</p>`:'')+(playerMode&&profile?.state.pending&&!m.profileMode&&!profile.state.conflict?` ${control('저장 다시 확인','retry-profile-save')}`:'')+(m.pending&&!m.conflict?` ${control('저장 다시 확인','retry')}`:'')+(notice.title&&m.hasSavedBytes?` ${control(sg2ExportLabel(m,{terminalPending}),'export')}`:'')+(profile?.state.recoveryRequired?` ${control('프로필 저장 안내','profile')}`:'');
